rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // aruma-ref probe block (temporary, S7-R). Every allow is guarded by rest[0].
    match /aruma-ref/{run}/{rest=**} {
      allow get: if rest[0] == 'sentinel' && (true);
      allow get: if rest[0] == 'dbg_true' && (debug(true));
      allow get: if rest[0] == 'dbg_eq1' && (debug(1) == 1);
      allow get: if rest[0] == 'dbg_ne1' && (debug(1) != 1);
      allow get: if rest[0] == 'dbg_str' && (debug('s') == 's');
      allow get: if rest[0] == 'dbg_map' && (debug({'a': 1}).a == 1);
      allow get: if rest[0] == 'dbg_not_false' && (!debug(false));
      allow get: if rest[0] == 'dbg_or_true' && (debug(true) || true);
      allow get: if rest[0] == 'dbg0_eq_null' && (debug() == null);
      allow get: if rest[0] == 'dbg0_ne_null' && (debug() != null);
      allow get: if rest[0] == 'dbg0_or_true' && (debug() == null || true);
      allow get: if rest[0] == 'dbg2_eq1' && (debug(1, 2) == 1);
      allow get: if rest[0] == 'dbg2_eq2' && (debug(1, 2) == 2);
      allow get: if rest[0] == 'dbg2_ne1' && (debug(1, 2) != 1);
      allow get: if rest[0] == 'dbg2_eq_list' && (debug(1, 2) == [1, 2]);
      allow get: if rest[0] == 'tok_provider_anon' && (request.auth.token.firebase.sign_in_provider == 'anonymous');
      allow get: if rest[0] == 'tok_n_int_eq2' && (request.auth.token.n_int == 2);
      allow get: if rest[0] == 'tok_n_two_eq2' && (request.auth.token.n_two == 2);
      allow get: if rest[0] == 'tok_n_frac_eq' && (request.auth.token.n_frac == 2.5);
      allow get: if rest[0] == 'tok_m_n_eq3' && (request.auth.token.m.n == 3);
      allow get: if rest[0] == 'tok_n_big_eq_exact' && (request.auth.token.n_big == 9007199254740993);
      allow get: if rest[0] == 'tok_n_big_ne_rounded' && (request.auth.token.n_big != 9007199254740992);
      allow get: if rest[0] == 'get_eq_null' && (get(/databases/$(database)/documents/aruma-ref/$(run)/missing/none) == null);
      allow get: if rest[0] == 'get_ne_null' && (get(/databases/$(database)/documents/aruma-ref/$(run)/missing/none) != null);
      allow get: if rest[0] == 'get_data_eq_null' && (get(/databases/$(database)/documents/aruma-ref/$(run)/missing/none).data == null);
      allow get: if rest[0] == 'get_or_true' && (get(/databases/$(database)/documents/aruma-ref/$(run)/missing/none) == null || true);
      allow get: if rest[0] == 'get_is_map' && (get(/databases/$(database)/documents/aruma-ref/$(run)/missing/none) is map);
      allow get: if rest[0] == 'exists_false' && (exists(/databases/$(database)/documents/aruma-ref/$(run)/missing/none) == false);
      allow get: if rest[0] == 'exists_true' && (exists(/databases/$(database)/documents/aruma-ref/$(run)/missing/none) == true);
      allow get: if rest[0] == 'get_fixture' && (get(/databases/$(database)/documents/aruma-ref/$(run)/fixture/doc).data.v == 1);
      allow get: if rest[0] == 'ord_read_src' && (resource.data.values() == [1, 2, 3, 4]);
      allow get: if rest[0] == 'ord_read_key' && (resource.data.values() == [2, 4, 3, 1]);
      allow get: if rest[0] == 'ord_read_keys_sorted' && (resource.data.keys() == ['a', 'b', 'm', 'z']);
      allow get: if rest[0] == 'tok_exp_int' && (request.auth.token.exp is int);
