      allow get: if rest[0] == 'tok_iat_int' && (request.auth.token.iat is int);
      allow get: if rest[0] == 'tok_iat_float' && (request.auth.token.iat is float);
      allow get: if rest[0] == 'tok_auth_time_int' && (request.auth.token.auth_time is int);
