      allow get: if rest[0] == 'tok_n_int_float' && (request.auth.token.n_int is float);
      allow get: if rest[0] == 'tok_n_two_int' && (request.auth.token.n_two is int);
      allow get: if rest[0] == 'tok_n_two_float' && (request.auth.token.n_two is float);
      allow get: if rest[0] == 'tok_n_frac_int' && (request.auth.token.n_frac is int);
