      allow get: if rest[0] == 'tok_n_huge_float' && (request.auth.token.n_huge is float);
      allow get: if rest[0] == 'tok_m_n_int' && (request.auth.token.m.n is int);
      allow get: if rest[0] == 'tok_m_n_float' && (request.auth.token.m.n is float);
