      allow create: if run == 's7r-20261024' && rest[0] == 'ord_src' && (request.resource.data.values() == [1, 2, 3, 4]);
      allow create: if run == 's7r-20261024' && rest[0] == 'ord_key' && (request.resource.data.values() == [2, 4, 3, 1]);
