      allow create: if run == 's7r-20261024' && rest[0] == 'ord_keys_src' && (request.resource.data.keys() == ['z', 'a', 'm', 'b']);
      allow create: if run == 's7r-20261024' && rest[0] == 'ord_rev_src' && (request.resource.data.values() == [4, 3, 2, 1]);
      allow create: if run == 's7r-20261024' && rest[0] == 'ord_rev_key' && (request.resource.data.values() == [2, 4, 3, 1]);
    }
  }
}

